package com.highpass.runspot.chat.service;
import com.highpass.runspot.auth.domain.User;import com.highpass.runspot.auth.domain.dao.UserRepository;import com.highpass.runspot.chat.domain.*;import com.highpass.runspot.chat.dto.*;import com.highpass.runspot.chat.exception.*;import com.highpass.runspot.chat.repository.*;import com.highpass.runspot.file.service.S3PresignService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor
public class ChatMessageService {private final ChatRoomRepository rooms;private final ChatRoomMemberRepository members;private final ChatMessageRepository messages;private final UserRepository users;private final S3PresignService files;
 @Transactional public ChatSendResponse send(Long userId,ChatSendRequest request){ChatRoomMember member=members.findByRoomIdAndUserIdAndLeftAtIsNull(request.roomId(),userId).orElseThrow(()->e(ChatErrorCode.NOT_ROOM_MEMBER));ChatRoom room=rooms.findDetail(request.roomId()).orElseThrow(()->e(ChatErrorCode.CHAT_ROOM_NOT_FOUND));if(room.getStatus()!=ChatRoomStatus.ACTIVE)throw e(ChatErrorCode.CHAT_ROOM_CLOSED);ChatMessage duplicate=messages.findByRoomIdAndClientMessageId(request.roomId(),request.clientMessageId()).orElse(null);if(duplicate!=null)return ChatSendResponse.from(duplicate,member.getRole()==ChatMemberRole.HOST);validate(request);User sender=users.findById(userId).orElseThrow(()->e(ChatErrorCode.USER_NOT_FOUND));files.link(userId,request.imageKeys());ChatMessage saved=messages.saveAndFlush(ChatMessage.create(room,sender,request.clientMessageId(),request.messageType(),request.content(),request.imageKeys()));room.updateLastMessage(saved.getId(),saved.getCreatedAt());return ChatSendResponse.from(saved,member.getRole()==ChatMemberRole.HOST);}
 private void validate(ChatSendRequest r){if(r.messageType()==ChatMessageType.TEXT&&(r.content()==null||r.content().isBlank())||r.messageType()==ChatMessageType.IMAGE&&r.imageKeys().isEmpty()||r.messageType()==ChatMessageType.SYSTEM)throw e(ChatErrorCode.INVALID_CHAT_MESSAGE);}
 private ChatException e(ChatErrorCode code){return new ChatException(code);}}
